 public static Entry get(String slug){Entry e=entries.get((slug==null?"":slug).toLowerCase(Locale.ROOT));return e!=null?e:new Entry(slug,UNVERIFIED,"New project: no reviewed firmware evidence.","","https://github.com/"+slug+"/blob/HEAD/README.md","https://github.com/"+slug+"/releases",new long[0]);}
 public static int project(String slug,int fw,String latest){Entry e=get(slug);if(e.state==REFERENCE)return REFERENCE;if(fw!=165)return UNVERIFIED;if(latest!=null&&!latest.isEmpty()&&!latest.equals(e.tag))return UNVERIFIED;return e.state;}
 public static int asset(String slug,int fw,String tag,long id){Entry e=get(slug);if(e.state==REFERENCE)return REFERENCE;if(fw!=165)return UNVERIFIED;if(!e.tag.equals(tag))return UNVERIFIED;for(long known:e.ids)if(known==id)return e.state;return UNVERIFIED;}
 public static String label(int state){return new String[]{"Author-confirmed SWI165", "Unverified for selected firmware", "Not supported on SWI165", "Reference project · no APK"}[state];}
 public static String section(int state){return new String[]{"SWI165 · AUTHOR-CONFIRMED RELEASES", "UNVERIFIED · REVIEW COMPATIBILITY", "SWI165 · EXPLICITLY UNSUPPORTED", "REFERENCE PROJECTS"}[state];}
